  <script>
    const APIBASE = window.location.origin;
    const WSBASE = window.location.protocol === "https:" ? "wss://" : "ws://" + window.location.host;
    let currentView = "homeView";
    let selectedMode = "sima";
    let ws = null;
    let currentJobId = null;
    function fetchWithRetry(url, options, retries = 3) {
      return new Promise(async (resolve, reject) => {
        for (let i = 0; i < retries; i++) {
          try {
            const response = await fetch(url, options);
            if (!response.ok || response.status === 500) throw new Error("Server error " + response.status);
            const data = await response.json();
            return resolve(data);
          } catch (error) {
            if (i === retries - 1) return reject(error);
            await new Promise(r => setTimeout(r, Math.pow(2, i) * 1000));
          }
        }
      });
    }
    class WebSocketManager {
      constructor(jobId) {
        this.jobId = jobId;
        this.ws = null;
        this.reconnectDelay = 1000;
        this.maxReconnectDelay = 30000;
        this.intentionalClose = false;
      }
      connect() {
        if (this.ws && (this.ws.readyState === WebSocket.CONNECTING || this.ws.readyState === WebSocket.OPEN)) return;
        this.intentionalClose = false;
        this.ws = new WebSocket(WSBASE + "/ws/" + this.jobId);
        this.ws.onopen = () => {this.reconnectDelay = 1000;};
        this.ws.onmessage = event => {
          try {
            const data = JSON.parse(event.data);
            updateJobStatus(data);
            if (["completed", "failed", "cancelled"].includes(data.status)) {
              this.intentionalClose = true; this.close();
              setTimeout(() => loadJobDetail(this.jobId), 1000);
            }
          } catch (error) { }
        };
        this.ws.onerror = () => { };
        this.ws.onclose = () => {
          if (!this.intentionalClose) {
            setTimeout(() => this.connect(), this.reconnectDelay);
            this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
          }
        };
      }
      close() {
        this.intentionalClose = true;
        if (this.ws) {this.ws.close(); this.ws = null;}
      }
    }
    function loadSettings() {
      try {
        const settings = localStorage.getItem("research-settings");
        return settings ? JSON.parse(settings) : {defaultMode: "sima", defaultTimeLimit: 10, defaultMaxSources: 100, theme: "dark"};
      } catch {return {defaultMode: "sima", defaultTimeLimit: 10, defaultMaxSources: 100, theme: "dark"};}
    }
    function saveSettings(settings) {
      try {
        localStorage.setItem("research-settings", JSON.stringify(settings));
        return true;
      } catch {return false;}
    }
    function applySettings() {
      const settings = loadSettings();
      document.getElementById("timeLimit").value = settings.defaultTimeLimit;
      document.getElementById("maxSources").value = settings.defaultMaxSources;
      selectedMode = settings.defaultMode;
      document.querySelectorAll("[data-mode]").forEach(opt => {
        opt.classList.toggle("active", opt.dataset.mode === settings.defaultMode);
      });
    }
    function getStatusText(status) {
      const statusMap = {
        pending: "Várakozik",
        running: "Fut",
        completed: "Kész",
        failed: "Hiba",
        cancelled: "Megszakítva"
      }; return statusMap[status] || status;
    }
    function formatDate(dateStr) {
      try {
        const date = new Date(dateStr);
        const now = new Date();
        const diffMs = now - date;
        const diffMins = Math.floor(diffMs / 60000);
        if (diffMins < 1) return "Most";
        if (diffMins < 60) return diffMins + " perce";
        if (diffMins < 1440) return Math.floor(diffMins / 60) + " órája";
        return Math.floor(diffMins / 1440) + " napja";
      } catch {return dateStr;}
    }
    function formatTime(timestamp) {
      try {
        const date = new Date(timestamp);
        return date.toLocaleTimeString("hu-HU", {hour: "2-digit", minute: "2-digit", second: "2-digit"});
      } catch {return timestamp;}
    }
    function escapeHtml(text) {
      const div = document.createElement("div"); div.textContent = text;
      return div.innerHTML;
    }
    function markdownToHtml(markdown) {
      let html = escapeHtml(markdown);
      html = html.replace(/^### (.*)$/gm, '<h3>$1</h3>')
        .replace(/^## (.*)$/gm, '<h2>$1</h2>')
        .replace(/^# (.*)$/gm, '<h1>$1</h1>')
        .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
        .replace(/\*(.+?)\*/g, '<em>$1</em>')
        .replace(/^- (.+)$/gm, '<li>$1</li>')
        .replace(/(<li>.*<\/li>)/g, '<ul>$1</ul>')
        .replace(/\n/g, '<p>')
        .replace(/<p><\/ul>/g, '</ul>');
      return html;
    }
    setTimeout(() => {document.getElementById("splash").classList.add("hide"); applySettings();}, 1800);
    document.querySelectorAll("[data-mode]").forEach(option => {
